     if d<bestdelta:bestdelta=d;bestmove=('r',a,x,b,y)
 # all swaps
 for a in range(len(seq)):
  for b in range(a,len(seq)):
   for x,ja in enumerate(seq[a]):
    ys=range(x+1,len(seq[b])) if a==b else range(len(seq[b]))
    for y in ys:
     jb=seq[b][y]
     if not elig[ja][b] or not elig[jb][a]:continue
     if a==b:
      ns=seq[a][:];ns[x],ns[y]=ns[y],ns[x];d=pc(a,ns)-costs[a]
     else:
      na=seq[a][:];nb=seq[b][:];na[x]=jb;nb[y]=ja;d=pc(a,na)+pc(b,nb)-costs[a]-costs[b]
     if d<bestdelta:bestdelta=d;bestmove=('s',a,x,b,y)
 if not bestmove: print('LOCAL',total,'round',rounds);break
 typ,a,x,b,y=bestmove
 if typ=='r':
  ji=seq[a].pop(x)
  if a==b and y>x:y-=1
  seq[b].insert(y,ji)
 else: seq[a][x],seq[b][y]=seq[b][y],seq[a][x]
 for q in {a,b}:costs[q]=pc(q,seq[q])
 total=sum(costs);save(total)
